        const boundListener = this.annotationModifiedListener;
        esm.eventTarget.addEventListener(toolsEvents.ANNOTATION_ADDED, boundListener);
        esm.eventTarget.addEventListener(toolsEvents.ANNOTATION_MODIFIED, boundListener);
        esm.eventTarget.addEventListener(toolsEvents.ANNOTATION_COMPLETED, boundListener);
